"""Author finite typed knowledge workflows, not a general runtime engine."""
from pathlib import Path
import json,hashlib
ROOT=Path(__file__).resolve().parents[3]
def cid(d):return 'K01-CL-'+d.replace('.','-')+'@1'
def rec(t,id,**v):return dict(id=id,revision=1,type=t,owner='K01',**v)
records=[];relations=[]
def workflow(id,d2,description,steps):
 wid='K01-WF-'+id;records.append(rec('Workflow',wid,d2='K01.'+d2,purpose=description,entry=wid+'-'+steps[0][0]+'@1',status='OFFLINE_KNOWLEDGE_CANDIDATE'))
 for j,(key,op,fields,claims,condition) in enumerate(steps):
  sid=wid+'-'+key;refs=[cid(x) for x in claims];records.append(rec('Step',sid,workflow=wid+'@1',operation=op,inputFields=fields,claimRefs=refs,condition=condition,status='CANDIDATE_ONLY'))
  relations.append(dict(type='contains',fromRef=wid+'@1',toRef=sid+'@1'))
  for ref in refs:relations.append(dict(type='uses_knowledge',fromRef=sid+'@1',toRef=ref))
  records.append(rec('Transition',sid+'-KNOWN',fromStep=sid+'@1',guard='KNOWN_VALID_CONDITIONS',toStep=wid+'-'+steps[j+1][0]+'@1' if j+1<len(steps) else None,outcome=None if j+1<len(steps) else 'BOUNDED_SYMBOLIC_CANDIDATE'))
  records.append(rec('Transition',sid+'-UNKNOWN',fromStep=sid+'@1',guard='MISSING_OR_UNSUPPORTED_CONDITIONS',toStep=None,outcome='UNKNOWN_NO_INFERENCE'))
  records.append(rec('Transition',sid+'-REJECT',fromStep=sid+'@1',guard='EXPLICIT_INVALID_OR_PROTECTED_CHANGE',toStep=None,outcome='REJECTED_NO_ADOPTION'))
workflow('INTERVAL','01','书写音程：辨识音高与拼写，再查级数及半音。',[('INPUT','WRITTEN_INPUT',['from','to','model'],['01.01.01'],'12TET普通西方书写，音区明确'),('CLASSIFY','INTERVAL_CLASSIFY',['from','to'],['01.04.02','01.05.01','01.06.01'],'保留完整方向/级数/性质，不用模12替代')])
workflow('TUNING','02','正频率音分、近似映射及残差。',[('RATIO','CENTS_RATIO',['f1','f2'],['02.04.01'],'正同单位频率'),('MAP','NEAREST_12TET',['f2','reference','rounding'],['02.06.01','02.04.02'],'参考、舍入和原值保留，匿名数学例非实测')])
workflow('TONAL','03','短暂主音化和新中心候选。',[('CONTEXT','TONAL_CONTEXT',['startingKey','chord','target'],['03.04.01','05.06.01'],'有限C/D7/G候选例，不作为通用自动调性识别'),('COMPARE','TONAL_COMPARE',['after','cadenceEvidence'],['03.04.02','03.04.03','05.06.02'],'查实际后文及句末，不由单一和弦决定')])
workflow('METER','04','有序分组和等分比例分开。',[('GROUP','GROUP_RATIONAL',['groups','unit'],['04.04.01','04.05.01','04.05.02'],'已声明分组及名义全音符单位'),('TUPLET','TUPLET_RATIONAL',['nominalQuarter','actual','normal','count'],['04.06.01','04.06.02','04.06.03'],'给定局部比例与名义音符，实际听感未知')])
workflow('HARMONY','05','和弦结构与实际调性功能分开。',[('STRUCTURE','SEVENTH_STRUCTURE',['root','notes'],['05.04.01','05.04.02','05.04.03'],'指定根音及四音完整传统三度叠置'),('FUNCTION','D7_FUNCTION',['key','next'],['05.06.01','05.06.02'],'有限D7→G在C或G的条件候选')])
workflow('COUNTERPOINT','06','指定H2局部二分音符规则检查。',[('RULE','H2_SCOPE',['ruleSet','meter','durations','fixed'],['06.02.02','06.12.01'],'仅H2普通2:1 4/4局部半音符'),('PASSING','H2_PASSING',['upper','fixed','strongIndex'],['06.04.01','06.05.01','06.12.01'],'强位协和；弱位不协和须级进经过，不认定整题')])
workflow('FORM','07','竞争曲式候选依比例、动机和中心。',[('INPUT','FORM_CONTEXT',['aMeasures','bMeasures','relatedMotif','harmony','independentTheme'],['07.01.01','07.05.01'],'明确片段长度、关联和和声'),('COMPARE','FORM_COMPARE',['aMeasures','bMeasures','relatedMotif','harmony','independentTheme'],['07.05.01','07.05.02'],'只输出竞争候选，不由ABA/时代唯一分类')])
workflow('NOTATION','08','TH-A01符号编辑保护及候选复核。',[('BASE','VOICE_TIMELINE',['baseline'],['08.05.01'],'正常4/4两声部，四分音符6tick'),('EDIT','PROTECTED_TUPLET_EDIT',['baseline','candidate','allowedTarget'],['04.06.01','08.05.02','08.06.03'],'只替换A第三拍，保护其它事件及小节元数据'),('CHECK','VISUAL_SOUND_FIELDS',['candidate'],['08.06.02','08.06.03'],'独立保留比例、视觉分组及播放名义字段；不声明实际回读')])
workflow('SET-CLASS','09','声明分段与约定后计算集合表示。',[('INPUT','SET_INPUT',['pitchClasses','segmentation','convention'],['09.04.01','09.04.02'],'非空整数模12集合，实际分段显式'),('NORMAL','SET_NORMAL',['pitchClasses','convention'],['09.07.01','09.10.01'],'指定完整F或R比较键，保留对称多解'),('PRIME','SET_PRIME_VECTOR',['pitchClasses','convention'],['09.07.02','09.08.01','09.08.02','09.08.03'],'同一约定比较倒影，向量不唯一决定同类')])
# Project workflow requirements (not source-backed professional claims).
records.extend([rec('ProjectConstraint','K01-CONSTRAINT-ANALYSIS-CONTEXT',d4='K01.09.01.02',required=['inputIdentity','segmentation','pitchConvention','tuning','ruleSet','unit'],status='PROJECT_CONTRACT_NOT_PROFESSIONAL_CLAIM',limits='缺任一不裁定竞争解释，真实工具版本另验。'),rec('ProjectConstraint','K01-CONSTRAINT-REVISION',d4='K01.09.03.02',required=['priorRevision','changeReason','changedEvidence','retestStatus','retainedAlternatives'],status='PROJECT_CONTRACT_NOT_PROFESSIONAL_CLAIM',limits='真实事务、回滚和工具回读归K09/K12；不以合成候选冒充。')])
records.extend([rec('AnalysisRevision','K01-ANALYSIS-V1',inputIdentity='synthetic-C-D7-G-v1',segmentation='three-symbols',pitchConvention='written-12TET',tuning='12TET',ruleSet='specified Western tonal analysis',unit='symbolic chord sequence',evidence=['C','D7','G'],labels=['V7/V','转G候选'],status='DRAFT_CANDIDATE'),rec('AnalysisRevision','K01-ANALYSIS-V2',inputIdentity='synthetic-C-D7-G-G7-C-v2',segmentation='five-symbols',pitchConvention='written-12TET',tuning='12TET',ruleSet='specified Western tonal analysis',unit='symbolic chord sequence',evidence=['C','D7','G','G7','C'],priorRevision='K01-ANALYSIS-V1@1',changeReason='后续G7–C证据',changedEvidence=['G7','C'],labels=['主音化候选'],retainedAlternatives=['转G候选'],retestStatus='SYMBOLIC_CHECKED',status='DRAFT_CANDIDATE')])
relations.append(dict(type='revises',fromRef='K01-ANALYSIS-V2@1',toRef='K01-ANALYSIS-V1@1'))
# TH-A01 original and candidate events have actual identity and tick duration, no external audio.
def ev(id,voice,pitch,start,duration,**v):return dict(id=id,voice=voice,pitch=pitch,start=start,duration=duration,nominal='quarter' if duration==6 else 'whole' if duration==24 else 'eighth',**v)
base=dict(meter='4/4',ticksPerQuarter=6,events=[ev('A1','A','C4',0,6),ev('A2','A','D4',6,6),ev('A3','A','E4',12,6),ev('A4','A','F4',18,6),ev('B1','B','C3',0,24)])
cand=dict(meter='4/4',ticksPerQuarter=6,events=[base['events'][0],base['events'][1],ev('A3a','A','E4',12,2,actual=3,normal=2,tuplet='start',playbackDuration=2),ev('A3b','A','F4',14,2,actual=3,normal=2,tuplet='continue',playbackDuration=2),ev('A3c','A','E4',16,2,actual=3,normal=2,tuplet='stop',playbackDuration=2),base['events'][3],base['events'][4]])
records.append(rec('SymbolicEditWitness','K01-TH-A01',baseline=base,candidate=cand,allowedTarget='A3',expected='SYMBOLIC_CHECKED',externalResult='UNKNOWN_NOT_EXECUTED',limits='合成符号候选，不是实际授权、宿主/导出或音乐效果。'))
stateRules=[dict(event='PROTECTED_CHANGE',fromStates=['DRAFT_CANDIDATE','SYMBOLIC_CHECKED'],toState='REJECTED',effect='retain baseline; no adoption'),dict(event='SYMBOLIC_PASS',fromStates=['DRAFT_CANDIDATE'],toState='SYMBOLIC_CHECKED',effect='bound to exact candidate and conditions, not external verified'),dict(event='INPUT_OR_RULE_CHANGE',fromStates=['DRAFT_CANDIDATE','SYMBOLIC_CHECKED'],toState='INVALIDATED',effect='old evidence retained, fresh candidate/retest required'),dict(event='EXTERNAL_EVIDENCE_MISSING',fromStates=['DRAFT_CANDIDATE','SYMBOLIC_CHECKED'],toState='UNKNOWN_EXTERNAL',effect='no host verification or rollback claim')]
out=dict(format='audio-kg-K01-domain-workflows/1',status='FINITE_OFFLINE_WITNESSES_NOT_RUNTIME',records=records,relations=relations,stateRules=stateRules,limits=['no actual audio, tool execution, authorization or universal theory engine','UNKNOWN and REJECTED never adopt candidate','project constraints distinct from formal professional Claim','T07 integration required for unified consumption'])
p=ROOT/'knowledge/K01/domain-workflows.json';p.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(json.dumps(dict(records=len(records),relations=len(relations),workflows=9,stateRules=len(stateRules))))
